# -*- coding: utf-8 -*-
import json
kb = json.load(open('kb.json', 'r', encoding='utf-8'))

# Batch 6 - symptoms & common diseases (30 entries)
E = {
'打嗝': "<span class='tag'>西医</span>膈肌阵发性痉挛。多为一过性（饱餐、碳酸饮料、情绪激动），持续>48小时为顽固性呃逆，需排查中枢（脑卒中、肿瘤）或膈神经刺激（食管裂孔疝、胃食管反流、肺炎）。治疗：Valsalva动作、饮用冰水、纸袋呼吸。顽固性：氯丙嗪、巴氯芬。<br><span class='tag'>中医</span>胃中寒冷（呃声沉缓+遇寒加重+得热则减+舌淡苔白脉迟缓）宜丁香散；胃火上逆（呃声洪亮+口臭烦渴+舌红苔黄脉滑数）宜竹叶石膏汤；脾胃阳虚（呃声低弱+气短乏力+舌淡苔白脉弱）宜理中丸加丁香；胃阴不足（呃声急促+口干舌燥+舌红少苔脉细数）宜益胃汤。针灸：攒竹、内关、足三里、膈俞。",
'口苦': "<span class='tag'>西医</span>胆汁反流（最常见，胆囊炎/胆石症）、胃食管反流GERD、口腔疾病（牙龈炎、牙周病）、药物副作用、肝胆疾病（肝炎、胆管炎）。晨起口苦多与夜间胃酸反流有关。诊断：口腔检查+肝胆B超+胃镜。<br><span class='tag'>中医</span>肝胆湿热（口苦+胁肋胀痛+目赤尿黄+舌红苔黄腻脉弦数）宜龙胆泻肝汤；肝郁化火（口苦+急躁易怒+头痛+舌红苔黄脉弦数）宜丹栀逍遥散；胃热（口苦+口臭+牙龈肿痛+舌红苔黄脉滑数）宜清胃散。针灸：太冲、阳陵泉、内庭。",
'口臭': "<span class='tag'>西医</span>80-90%为口腔来源：牙龈炎、牙周炎、舌苔细菌、龋齿。非口腔来源：鼻窦炎、扁桃体结石、GERD、肺部感染（厌氧菌产生硫化物）、肝病（肝臭）、肾病（尿臭）、糖尿病（酮臭）、代谢性口臭。<br><span class='tag'>中医</span>胃热上蒸（口臭+口渴+牙龈肿痛+舌红苔黄脉滑数）宜清胃散；食积胃肠（口臭+脘腹胀满+嗳腐吞酸+苔厚腻脉滑）宜保和丸；肝胆湿热（口苦口臭+胁痛+尿黄+舌红苔黄腻脉弦数）宜龙胆泻肝汤。针灸：内庭、合谷、足三里。",
'食欲不振': "<span class='tag'>西医</span>厌食/纳差。病因：消化系统（胃炎、肝炎、胃癌）、感染（结核、病毒感染）、精神因素（抑郁、焦虑）、药物、内分泌（甲减、Addison病）、肿瘤恶病质。持续>2周需就医。<br><span class='tag'>中医</span>脾胃虚弱（食少+乏力+面色萎黄+舌淡苔白脉弱）宜参苓白术散；脾胃湿热（纳差+身重+苔黄腻脉滑数）宜连朴饮；肝郁脾虚（纳差+情志抑郁+腹胀+脉弦）宜逍遥散；食积内停（厌食+嗳腐+脘腹胀满+苔厚腻脉滑）宜保和丸。针灸：足三里、中脘、脾俞。",
'黄疸': "<span class='tag'>西医</span>血胆红素>34μmol/L时皮肤巩膜黄染。分类：①肝前性（溶血性，贫血+脾大，间接胆红素升高）；②肝细胞性（肝炎、肝硬化、药物性肝损，直接+间接均升高，ALT/AST升高）；③肝后性（梗阻性，胆石症、肿瘤，直接胆红素升高，ALP/GGT升高，大便白陶土色）。诊断：胆红素分类+肝功能+腹部B超。<br><span class='tag'>中医</span>阳黄-热重于湿（黄色鲜明+身热+口苦+舌红苔黄腻脉弦数）宜茵陈蒿汤；阳黄-湿重于热（黄色晦暗+身重+苔白腻脉濡缓）宜茵陈五苓散；阴黄（黄色晦暗如烟熏+畏寒+舌淡苔白腻脉沉迟）宜茵陈术附汤。针灸：胆俞、阳陵泉、太冲、至阳。",
'鼻塞': "<span class='tag'>西医</span>鼻腔通气不畅。常见原因：①急性鼻炎（感冒，3-7天自愈）；②过敏性鼻炎（花粉/尘螨，季节性+打喷嚏清水涕）；③慢性鼻炎（长期鼻塞，黏膜肥厚）；④鼻中隔偏曲（单侧鼻塞，需手术矫正）；⑤鼻息肉（双侧持续鼻塞）；⑥鼻窦炎（脓涕+面部胀痛+嗅觉下降）。治疗：病因治疗+鼻用减充血剂（羟甲唑啉，<7天避免反跳）；鼻用激素（布地奈德，过敏性鼻炎一线）。<br><span class='tag'>中医</span>风寒犯鼻（鼻塞+流清涕+恶寒+苔薄白脉浮紧）宜辛夷散；风热犯鼻（鼻塞+黄涕+发热+苔薄黄脉浮数）宜银翘散合苍耳子散；肺脾气虚（鼻塞反复+面色萎黄+舌淡苔白脉弱）宜补中益气汤合苍耳子散。针灸：迎香、印堂、合谷、风池。",
'打鼾': "<span class='tag'>西医</span>睡眠时上气道部分塌陷→气流振动软腭/悬雍垂→鼾声。分型：①单纯性打鼾（无呼吸暂停，无日间嗜睡）；②阻塞性睡眠呼吸暂停OSA（打鼾+呼吸暂停+日间嗜睡+晨起头痛）。OSA诊断：睡眠监测PSG（AHI>5）。OSA危害：高血压、冠心病、卒中、糖尿病。危险因素：肥胖、男性、颈粗、饮酒。治疗：减肥、侧卧位、戒酒、CPAP呼吸机（中重度OSA一线）、手术（UPPP）。<br><span class='tag'>中医</span>痰湿内阻（鼾声如雷+体胖+嗜睡+苔白腻脉滑）宜二陈汤合三子养亲汤；肺脾气虚（鼾声低弱+少气懒言+舌淡苔白脉弱）宜补中益气汤。针灸：丰隆、阴陵泉、天突。",
'牙龈出血': "<span class='tag'>西医</span>牙龈出血。局部原因（90%）：牙龈炎、牙周炎（菌斑刺激，最常见）、刷牙不当、牙石。全身原因：血小板减少（ITP、白血病、再障）、凝血功能障碍（血友病、肝病）、药物（抗凝药华法林）、维生素C缺乏（坏血病）。诊断：口腔检查+血常规+凝血功能。<br><span class='tag'>中医</span>胃火炽盛（牙龈出血+口臭+牙龈肿痛+舌红苔黄脉滑数）宜清胃散合泻心汤；阴虚火旺（牙龈渗血+齿摇+五心烦热+舌红少苔脉细数）宜知柏地黄丸；脾气虚弱（牙龈渗血+面色萎黄+神疲+舌淡脉弱）宜归脾汤。针灸：合谷、内庭、足三里。",
'便秘': None,  # already expanded, skip
'腹泻': None,
'恶心': None,
'呕吐': None,
'咽喉异物感': "<span class='tag'>西医</span>梅核气/咽异物感。患者感觉咽喉有异物堵塞，吞咽无碍，空咽时明显。鉴别：排除器质性病变（咽炎、食管炎、食管肿瘤、甲状腺肿大）后考虑功能性疾病。常见于焦虑、抑郁、胃食管反流。<br><span class='tag'>中医</span>肝气郁结（咽喉异物感+情志不畅+胸胁胀满+脉弦）宜半夏厚朴汤（经典方）；痰气交阻（异物感+胸闷+苔白腻脉弦滑）宜四七汤。针灸：天突、膻中、太冲、内关。",
'消瘦': "<span class='tag'>西医</span>6个月内体重下降>5%需警惕。原因：①恶性肿瘤（消瘦+食欲下降+疼痛，需全面筛查）；②甲状腺功能亢进（消瘦+怕热+心悸手抖）；③糖尿病（三多一少）；④慢性感染（结核、HIV）；⑤消化吸收不良；⑥精神性厌食；⑦甲亢。<br><span class='tag'>中医</span>脾胃虚弱（消瘦+食少+乏力+舌淡苔白脉弱）宜参苓白术散；胃阴虚（消瘦+口干+纳差+舌红少苔脉细数）宜益胃汤；虫积（消瘦+嗜食异物+面黄+腹胀+舌苔剥落）宜化虫丸。针灸：足三里、中脘、脾俞。",
'怕冷': "<span class='tag'>西医</span>畏寒/怕冷。原因：①甲状腺功能减退（最常见，代谢率下降）；②贫血（血红蛋白低，组织缺氧）；③低血压/循环不良；④营养不良；⑤自主神经功能紊乱；⑥环境因素。诊断：甲功+血常规+血压。<br><span class='tag'>中医</span>阳虚内寒（畏寒肢冷+面色苍白+腰膝酸软+舌淡胖苔白脉沉迟）宜金匮肾气丸或理中丸；气血两虚（畏寒+面色萎黄+乏力心悸+舌淡脉细弱）宜八珍汤。针灸：关元、气海、足三里、命门。",
'口干': "<span class='tag'>西医</span>口干症。原因：①饮水不足/脱水；②张口呼吸；③药物副作用（抗胆碱能药、抗抑郁药）；④干燥综合征Sjogren（自身免疫，口干+眼干+关节痛，抗SSA/SSB阳性）；⑤糖尿病（多饮多尿）；⑥头颈部放疗后。<br><span class='tag'>中医</span>胃热炽盛（口干+口臭+牙龈肿+舌红苔黄脉滑数）宜玉女煎；阴虚内热（口干不欲饮+五心烦热+盗汗+舌红少苔脉细数）宜知柏地黄丸；津液亏虚（口干+皮肤干燥+尿少+舌红少津脉细数）宜沙参麦冬汤。针灸：廉泉、三阴交、太溪。",
'泡沫尿': "<span class='tag'>西医</span>尿液中泡沫增多。原因：①生理性（尿流速度快、浓缩尿，短暂出现，正常）；②蛋白尿（肾脏疾病标志：肾炎、肾病综合征、糖尿病肾病，尿蛋白>150mg/日，需尿常规+尿蛋白定量）；③胆红素尿（肝胆疾病，尿色深黄）。持续性泡沫尿需查尿常规。<br><span class='tag'>中医</span>肾气不固（小便频数泡沫多+腰膝酸软+舌淡苔白脉沉弱）宜金匮肾气丸；脾肾阳虚（泡沫尿+水肿+畏寒+舌淡胖脉沉迟）宜真武汤。针灸：肾俞、命门、三阴交。",
'排尿困难': "<span class='tag'>西医</span>排尿费力、尿线变细、尿等待。常见原因：①良性前列腺增生BPH（中老年男性最常见，尿频+排尿困难+夜尿增多，B超确诊）；②尿道狭窄（外伤/感染后）；③前列腺炎；④神经源性膀胱（糖尿病、脊髓损伤）；⑤泌尿系感染。BPH治疗：alpha阻滞剂（坦索罗辛）、5alpha还原酶抑制剂（非那雄胺），严重时手术。<br><span class='tag'>中医</span>湿热下注（排尿困难+尿黄+舌红苔黄腻脉滑数）宜八正散；肾阳虚衰（排尿无力+面色苍白+腰膝酸冷+舌淡脉沉迟）宜济生肾气丸；中气下陷（小腹坠胀+排尿无力+乏力+舌淡脉弱）宜补中益气汤。针灸：中极、三阴交、关元。",
'月经量多': "<span class='tag'>西医</span>月经出血量>80ml/周期或经期>7天。原因：①功能失调性子宫出血DUB（无器质性病变，激素失调）；②子宫肌瘤（黏膜下肌瘤最易致多量出血）；②子宫腺肌症；③子宫内膜息肉；④凝血功能障碍；⑤IUD避孕环；⑥排卵障碍。诊断：妇科超声+性激素+血常规。治疗：激素调节（口服避孕药）、止血药、手术（肌瘤切除、内膜消融）。<br><span class='tag'>中医</span>气虚不摄（量多色淡+乏力+气短+舌淡脉弱）宜举元煎；血热妄行（量多色鲜红+口渴+舌红苔黄脉滑数）宜保阴煎；瘀血阻络（量多色暗有块+腹痛+舌紫暗脉涩）宜失笑散合桃红四物汤。针灸：三阴交、隐白、关元。",
'月经量少': "<span class='tag'>西医</span>月经出血量<20ml或经期<2天。原因：①卵巢功能减退（围绝经期、早衰）；②多囊卵巢综合征PCOS；③过度节食/运动；④精神压力；⑤宫腔粘连（人流术后）；⑥甲减；⑦高泌乳素血症。诊断：性激素六项+妇科超声。<br><span class='tag'>中医</span>血虚（量少色淡+面色萎黄+头晕+舌淡脉细）宜小营煎；肾虚（量少+腰膝酸软+舌淡脉沉弱）宜归肾丸；血瘀（量少色暗有块+痛经+舌紫暗脉涩）宜桃红四物汤；痰湿（量少+形体肥胖+白带多+苔白腻脉滑）宜苍附导痰丸。针灸：三阴交、血海、足三里。",
'经期延长': "<span class='tag'>西医</span>经期>7天。原因：①黄体功能不全（排卵后孕酮不足，内膜脱落不全）；②子宫肌瘤；③子宫内膜息肉；④子宫腺肌症；⑤凝血障碍；⑥IUD。治疗：激素调节、止血、手术。<br><span class='tag'>中医</span>气虚（经期延长+色淡+乏力+舌淡脉弱）宜举元煎；阴虚内热（经期延长+量少色红+五心烦热+舌红少苔脉细数）宜两地汤；瘀血（经期延长+色暗有块+腹痛+舌紫暗脉涩）宜桃红四物汤。针灸：三阴交、隐白、关元。",
'性交痛': "<span class='tag'>西医</span>性交时疼痛。女性原因：①阴道痉挛（心理因素为主）；②阴道干涩（绝经后雌激素下降）；③子宫内膜异位症（深部性交痛）；④盆腔炎；⑤阴道炎。男性原因：①前列腺炎；②包皮过长/包茎；③尿道炎。诊断：妇科检查+超声。<br><span class='tag'>中医</span>肝气郁结（性交痛+情志不畅+胸胁胀满+脉弦）宜逍遥散；肝肾阴虚（性交痛+腰膝酸软+口干+舌红少苔脉细数）宜知柏地黄丸；寒湿凝滞（性交痛+小腹冷痛+得温则减+舌淡苔白脉沉紧）宜少腹逐瘀汤。针灸：太冲、三阴交、关元。",
'产后恶露不尽': "<span class='tag'>西医</span>产后恶露（血液+分泌物）持续时间>6周或量多。原因：①胎盘残留（B超确诊，需清宫）；②子宫复旧不良（宫缩乏力）；③感染（子宫内膜炎，伴发热恶臭）；④凝血功能障碍。诊断：妇科超声+血常规。治疗：缩宫素+抗生素（感染时）+清宫（残留时）。<br><span class='tag'>中医</span>气虚（恶露不绝+色淡质稀+乏力+舌淡脉弱）宜补中益气汤；血瘀（恶露色暗有块+腹痛拒按+舌紫暗脉涩）宜生化汤；血热（恶露色红量多+口渴+舌红苔黄脉滑数）宜保阴煎。针灸：三阴交、关元、气海。",
'小儿夜啼': "<span class='tag'>西医</span>婴儿夜间频繁哭闹。原因：①饥饿/尿湿（最常见）；②肠绞痛（2-3周至3-4月龄，傍晚哭闹、蜷腿、排气后缓解）；③出牙痛；④感染（中耳炎、尿路感染）；⑤胃食管反流。一般6月龄后自行缓解。<br><span class='tag'>中医</span>脾寒气滞（夜间啼哭+腹部喜温+面色青白+舌淡苔白脉沉紧）宜乌药散；心热扰神（夜间啼哭+烦躁不安+面赤唇红+舌尖红脉细数）宜导赤散；惊恐伤神（夜间惊哭+面色青灰+梦中惊惕+舌无明显变化脉弦）宜远志丸。针灸：神门、百会、中脘。",
'小儿厌食': "<span class='tag'>西医</span>儿童食欲持续低下>2个月。原因：①不良饮食习惯（零食过多、喂养不当）；②微量元素缺乏（锌缺乏最常见）；③消化系统疾病（胃炎、HP感染）；④心理因素（强迫进食、情绪问题）；⑤感染/慢性疾病。<br><span class='tag'>中医</span>脾胃虚弱（不思乳食+面色少华+乏力+舌淡苔薄白脉缓弱）宜参苓白术散；脾胃不和（厌恶进食+嗳气+脘腹胀满+苔白腻脉缓）宜不换金正气散；胃阴不足（食少+口干+皮肤干燥+舌红少津苔剥脉细数）宜养胃增液汤。针灸：足三里、中脘、四缝（点刺）。",
'落枕': "<span class='tag'>西医</span>颈部肌肉急性痉挛疼痛，晨起发病。原因：睡姿不良、颈部受凉、枕头不当。表现：颈部一侧疼痛、活动受限，头偏向患侧。多1-3天自愈。治疗：热敷、NSAIDs、轻柔拉伸。<br><span class='tag'>中医</span>风寒客络（颈项强痛+恶寒+苔薄白脉浮紧）宜葛根汤；气滞血瘀（颈痛固定+转侧不利+舌暗脉涩）宜活血舒筋汤。针灸：落枕穴、风池、肩井、后溪。",
'鸡眼': "<span class='tag'>西医</span>局部皮肤圆锥形角质增生，压迫真皮神经→疼痛。好发：足底、趾间、趾背受压摩擦处。病因：穿鞋不当（过紧/过松/高跟鞋）、足部畸形（扁平足、拇外翻）。治疗：①鸡眼膏（水杨酸贴）；②冷冻/激光；③手术切除（复发率低）。预防：穿宽松鞋、减少摩擦。<br><span class='tag'>中医</span>外治为主：鸦胆子仁捣敷、水杨酸粉外贴。内服：肝郁血瘀（局部压痛+舌暗脉涩）宜桃红四物汤。针灸：阿是穴围刺。",
'荨麻疹慢性': "<span class='tag'>西医</span>风团反复发作>6周。病因复杂：自身免疫（慢性自身免疫性荨厥最常见）、物理因素（寒冷、压力）、慢性感染（HP、幽门螺杆菌）、食物不耐受。症状：风团伴瘙痒，每次<24小时消退，不留痕迹。治疗：二代抗组胺药（西替利嗪、氯雷他定，足量后加倍加用），严重者加用奥马珠单抗。<br><span class='tag'>中医</span>风邪犯表（风团色红+瘙痒+遇风加重+脉浮）宜消风散；风寒束表（风团色白+遇冷加重+舌淡苔白脉浮紧）宜桂枝麻黄各半汤；血虚风燥（反复发作+皮肤干燥+舌淡脉细）宜当归饮子。针灸：曲池、血海、风市、三阴交。",
'斑秃': "<span class='tag'>西医</span>局限性非瘢痕性脱发，圆形/椭圆形秃发斑。病因：自身免疫（T细胞攻击毛囊），常与精神应激相关。可自愈（50%半年内），也可进展为全秃/普秃。治疗：局部外用强效激素、局部注射曲安奈德、米诺地尔外用、接触免疫疗法（二苯环丙烯酮DPCP）。<br><span class='tag'>中医</span>血虚风燥（突然脱发+头皮瘙痒+面色萎黄+舌淡脉细）宜神应养真丹；气滞血瘀（脱发+情志抑郁+胸胁胀痛+舌紫暗脉涩）宜通窍活血汤；肝肾不足（脱发+腰膝酸软+头晕+舌红少苔脉细数）宜七宝美髯丹。针灸：百会、风池、太冲、三阴交。",
'心力衰竭': "<span class='tag'>西医</span>心脏泵血功能下降。分型：左心衰（呼吸困难+乏力+端坐呼吸+肺水肿）、右心衰（下肢水肿+颈静脉怒张+肝大）。病因：冠心病、高血压、心肌病、瓣膜病。诊断：BNP/NT-proBNP（重要标志物）、心脏超声EF值（<40%为射血分数降低型）。治疗：利尿剂、ACEI/ARB/ARNI、beta阻滞剂、螺内酯、SGLT2i（新型一线）。终末期考虑CRT/ICD/心脏移植。<br><span class='tag'>中医</span>心肺气虚（心悸气短+乏力+舌淡苔白脉弱）宜养心汤合补肺汤；气阴两虚（心悸+气短+口干+舌红少苔脉细数）宜生脉散；阳虚水泛（心悸+下肢水肿+畏寒+舌淡胖脉沉迟）宜真武汤合五苓散；痰瘀互结（胸闷+咳嗽痰多+唇甲青紫+舌紫暗脉涩）宜血府逐瘀汤合葶苈大枣泻肺汤。针灸：内关、心俞、膻中、水分。",
'肺心病': "<span class='tag'>西医</span>慢性肺源性心脏病，由COPD、肺结核、肺间质纤维化等慢性肺病→肺动脉高压→右心室肥大→右心衰竭。症状：原发病症状+右心衰（下肢水肿+颈静脉怒张+肝大）。诊断：胸片（右心室增大）、心脏超声（肺动脉压力）、血气分析。治疗：控制感染（核心）、氧疗（长期低流量吸氧）、利尿、强心（慎用，肺心病对洋地黄敏感）。<br><span class='tag'>中医</span>肺肾气虚（咳嗽气促+动则喘甚+腰膝酸软+舌淡苔白脉沉弱）宜补肺汤合金匮肾气丸；痰浊壅肺（咳喘痰多+胸闷+苔白腻脉滑）宜苏子降气汤；阳虚水泛（下肢水肿+心悸+畏寒+舌淡胖脉沉迟）宜真武汤合五苓散。针灸：肺俞、肾俞、膻中、足三里。",
}

count = 0
for i, e in enumerate(kb):
    t = e.get('t', '')
    if t in E and E[t] is not None and len(e.get('c','')) < 100:
        kb[i]['c'] = E[t]
        count += 1

with open('kb.json', 'w', encoding='utf-8') as f:
    json.dump(kb, f, ensure_ascii=False, indent=2)
print(f'Expanded: {count}')
